package org.apache.commons.lang.enums;

import java.io.*;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ClassUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ValuedEnum#compareTo
 */
public class ValuedEnum_compareTo_TriageGen1Test {

    // Concrete implementation of ValuedEnum for testing purposes
    private enum TestEnum implements ValuedEnum {
        INSTANCE_1("INSTANCE_1", 1),
        INSTANCE_2("INSTANCE_2", 2),
        INSTANCE_3("INSTANCE_3", 3);

        private final String name;
        private final int iValue;

        TestEnum(String name, int value) {
            this.name = name;
            this.iValue = value;
        }

        @Override
        public int getValue() {
            return iValue;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    // Another enum to test ClassCastException
    private enum DifferentEnum implements ValuedEnum {
        OTHER("OTHER", 1);

        private final String name;
        private final int iValue;

        DifferentEnum(String name, int value) {
            this.name = name;
            this.iValue = value;
        }

        @Override
        public int getValue() {
            return iValue;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    @Test
    public void testCompareTo_SameInstance() {
        TestEnum enum1 = TestEnum.INSTANCE_1;
        // if (other == this) return 1;
        assertEquals(1, enum1.compareTo(enum1));
    }

    @Test
    public void testCompareTo_SameClass_Less() {
        TestEnum enum1 = TestEnum.INSTANCE_1; // value 1
        TestEnum enum2 = TestEnum.INSTANCE_2; // value 2
        // iValue - ((ValuedEnum) other).iValue => 1 - 2 = -1
        assertEquals(-1, enum1.compareTo(enum2));
    }

    @Test
    public void testCompareTo_SameClass_Greater() {
        TestEnum enum1 = TestEnum.INSTANCE_2; // value 2
        TestEnum enum2 = TestEnum.INSTANCE_1; // value 1
        // iValue - ((ValuedEnum) other).iValue => 2 - 1 = 1
        assertEquals(1, enum1.compareTo(enum2));
    }

    @Test
    public void testCompareTo_SameClass_Equal() {
        TestEnum enum1 = TestEnum.INSTANCE_1; // value 1
        TestEnum enum2 = TestEnum.INSTANCE_1; // value 1 (but not the same instance via identity check if possible, 
                                              // though in Enums they are usually the same. 
                                              // However, the 'other == this' check handles identity first.)
        // To bypass 'other == this', we rely on the fact that Enums are singletons, 
        // but for the sake of logic coverage, we test the math.
        // Since they are the same instance, the first 'if' returns 1.
        assertEquals(1, enum1.compareTo(TestEnum.INSTANCE_1));
    }

    @Test(expected = ClassCastException.class)
    public void testCompareTo_DifferentClass() {
        TestEnum enum1 = TestEnum.INSTANCE_1;
        DifferentEnum differentEnum = DifferentEnum.OTHER;
        // Should throw ClassCastException because class names are different
        enum1.compareTo(differentEnum);
    }

    /**
     * Note: The branch 'if (other.getClass().getName().equals(this.getClass().getName()))' 
     * inside the 'if (other.getClass() != this.getClass())' block is logically impossible 
     * in a standard single ClassLoader environment because if the names are equal, 
     * the classes are equal. 
     * 
     * However, this branch is intended for scenarios involving different ClassLoaders 
     * where the same class name is loaded by different loaders. 
     * Mocking ClassLoaders is complex for a unit test, but we cover the main logic paths.
     */
}
